import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const root='/home/josh/projects/klem';
const source=JSON.parse(await readFile('/tmp/klem-fresh-unsu-source.json','utf8'));
const cli='/nix/store/sbkbpzhakddagl5i06r54n0sfkkwd54z-klem-0.1.0/bin/klem';
const db=root+'/data/dictionaries/krdict/krdict.db';
const {chromium}=createRequire(root+'/web/package.json')('playwright');
const browser=await chromium.launch({executablePath:'/nix/store/g0yvxs8p2ijrvmxpd5mim1ni0fyk9bnh-chromium-154.0.8037.57/bin/chromium',args:['--no-sandbox']});
const captures=[],errors=[];
try {
 const page=await browser.newPage({viewport:{width:1440,height:1000},acceptDownloads:true});
 page.on('pageerror',e=>errors.push(String(e)));await page.goto('http://127.0.0.1:41017');
 for(const passage of source.selected_passages) {
  for(const encoding of ['NFC','NFD']) {
   const text=passage.text.normalize(encoding);
   await page.getByLabel('Dictionary matches only').uncheck();
   await page.getByLabel('Your sentence',{exact:true}).fill(text);
   const wait=page.waitForResponse(r=>r.url().endsWith('/api/analyze'));
   await page.getByRole('button',{name:'Analyze sentence',exact:true}).click();
   const res=await wait;assert.equal(res.status(),200);const api=await res.json();
   await page.waitForFunction(t=>document.querySelector('.sentence')?.textContent===t,text);
   const checks=[];
   for(const [mode,flag] of [['raw',null],['headword','--dict-only'],['compatible','--dict-compatible']]) {
    if(flag){await page.getByLabel('Dictionary matches only').check();if(mode==='compatible')await page.getByLabel('Exclude known grammar conflicts').check();else await page.getByLabel('Exclude known grammar conflicts').uncheck();}
    else await page.getByLabel('Dictionary matches only').uncheck();
    const records=execFileSync(cli,['text','-','--dictionary',db,...(flag?[flag]:[])],{input:text,encoding:'utf8'}).trim().split('\n').map(JSON.parse);
    const download=page.waitForEvent('download');await page.getByRole('button',{name:'Export JSON',exact:true}).click();
    const exported=JSON.parse(await readFile(await(await download).path(),'utf8'));assert.deepEqual(exported.records,records);
    checks.push({mode,cli_records:records,exported_records:exported.records});
   }
   await page.getByLabel('Dictionary matches only').uncheck();
   const diagrams=await page.getByRole('region',{name:'Sentence breakdown',exact:true}).locator('.breakdown-word').evaluateAll(words=>words.map(word=>({surface:word.querySelector('.breakdown-surface > span')?.textContent,selected:word.querySelector('select')?.value,parts:[...word.querySelectorAll('.breakdown-part')].map(part=>({form:part.querySelector('.part-form')?.textContent,label:part.querySelector('.part-gloss')?.textContent,title:part.getAttribute('title')}))})));
   const words=api.records.filter(r=>r.analysis);assert.equal(diagrams.length,words.length);
   diagrams.forEach((d,i)=>{assert.equal(d.surface,words[i].surface);assert.ok(d.parts.length);});
   const screenshots={};
   if(encoding==='NFC') {
    const region=page.getByRole('region',{name:'Sentence breakdown',exact:true});await region.scrollIntoViewIfNeeded();
    const desktop='/tmp/klem-fresh-unsu-'+passage.paragraph_index+'-desktop.png';await page.screenshot({path:desktop});screenshots.desktop=desktop;
    await page.setViewportSize({width:390,height:844});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
    await region.scrollIntoViewIfNeeded();const mobile='/tmp/klem-fresh-unsu-'+passage.paragraph_index+'-mobile.png';await page.screenshot({path:mobile});screenshots.mobile=mobile;
    await page.setViewportSize({width:1440,height:1000});
   }
   captures.push({passage_id:passage.id,paragraph_index:passage.paragraph_index,encoding,request:{text},response:api,checks,diagrams,screenshots});
  }
 }
 assert.deepEqual(errors,[]);
 const hash=async p=>createHash('sha256').update(await readFile(p)).digest('hex');
 await writeFile('/tmp/klem-fresh-unsu-browser.json',JSON.stringify({source_sha256:await hash('/tmp/klem-fresh-unsu-source.json'),cli_sha256:await hash(cli),dictionary_sha256:await hash(db),producer_sha256:await hash('/tmp/klem-fresh-passage-browser.mjs'),captures,errors,scope:'Actual diagrams and all three export modes for four uniformly selected unseen paragraphs in NFC/NFD. Linguistic quality and default-gloss ambiguities require separate explicit review.'},null,2)+'\n');
 console.log('Verified eight original-passage API/browser renders, 24 CLI/export comparisons, exact input preservation and desktop/mobile layout.');
} finally {await browser.close();}

