import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFile,writeFile} from 'node:fs/promises';
const root='/home/josh/projects/klem';
const source=JSON.parse(await readFile('/tmp/klem-fresh-unsu-source.json','utf8'));
const {chromium}=createRequire(root+'/web/package.json')('playwright');
const browser=await chromium.launch({executablePath:'/nix/store/g0yvxs8p2ijrvmxpd5mim1ni0fyk9bnh-chromium-154.0.8037.57/bin/chromium',args:['--no-sandbox']});
const captures=[];
try {
 const page=await browser.newPage({viewport:{width:1440,height:1000}});
 await page.goto('http://127.0.0.1:41017');
 const passage=source.selected_passages.find(p=>p.paragraph_index===81);
 for(const encoding of ['NFC','NFD']) {
  const text=passage.text.normalize(encoding);
  await page.getByLabel('Your sentence',{exact:true}).fill(text);
  const wait=page.waitForResponse(r=>r.url().endsWith('/api/analyze'));
  await page.getByRole('button',{name:'Analyze sentence',exact:true}).click();
  const response=await wait;assert.equal(response.status(),200);
  const api=await response.json();
  await page.waitForFunction(t=>document.querySelector('.sentence')?.textContent===t,text);
  const word=api.records.find(r=>r.surface.normalize('NFC')==='먹지를');
  const index=word.analysis.analyses.findIndex(a=>a.lemmas.length===1&&a.lemmas[0].text==='먹다'&&a.morphemes.map(m=>m.form).join(',')==='지,를');
  assert.ok(index>=0);
  const cards=page.getByRole('region',{name:'Sentence breakdown',exact:true}).locator('.breakdown-word').filter({has:page.locator('.breakdown-surface > span',{hasText:text.includes('ᄆ')?'먹지를':'먹지를'})});
  assert.equal(await cards.count(),2);
  for(let occurrence=0;occurrence<2;occurrence++) {
   const card=cards.nth(occurrence);
   const before=await card.locator('select').inputValue();
   await card.locator('select').selectOption(String(index));
   const forms=await card.locator('.part-form').allTextContents();
   assert.deepEqual(forms,['먹','지','를']);
   captures.push({passage_id:passage.id,encoding,occurrence,before_selected_index:Number(before),selected_index:index,analysis:word.analysis.analyses[index],forms,labels:await card.locator('.part-gloss').allTextContents()});
  }
 }
 await writeFile('/tmp/klem-fresh-unsu-options.json',JSON.stringify({captures,scope:'Actual user selection of preserved 먹다 + 지 + 를 alternatives for both occurrences in NFC/NFD. No contextual ranking, sense disambiguation or gold judgment claimed.'},null,2)+'\n');
 console.log('Verified four real dropdown selections reveal 먹 + 지 + 를 while preserving the noun alternative.');
} finally {await browser.close();}
